<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_admin();
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $id=(int)($_POST['id']??0); $action=(string)($_POST['action']??'');
 if ($action==='remove_rating') db()->prepare('DELETE FROM project_ratings WHERE id=?')->execute([$id]);
 elseif ($action==='remove_like') db()->prepare('DELETE FROM project_likes WHERE id=?')->execute([$id]);
 else { flash('Unknown moderation action.','error'); redirect('admin/engagement.php'); }
 flash('Engagement entry removed.'); redirect('admin/engagement.php');
}
$projects=all_projects('p.deleted_at IS NULL');
$votes=db()->query('SELECT r.id,r.stars,r.visitor_hash,r.created_at,r.updated_at,p.title FROM project_ratings r JOIN projects p ON p.id=r.project_id ORDER BY r.updated_at DESC LIMIT 40')->fetchAll();
$likes=db()->query('SELECT l.id,l.visitor_hash,l.created_at,p.title FROM project_likes l JOIN projects p ON p.id=l.project_id ORDER BY l.created_at DESC LIMIT 40')->fetchAll();
$dist=db()->query('SELECT stars,COUNT(*) total FROM project_ratings GROUP BY stars ORDER BY stars DESC')->fetchAll();
$recentSpike=db()->query('SELECT p.title,COUNT(*) total FROM project_likes l JOIN projects p ON p.id=l.project_id WHERE l.created_at > UTC_TIMESTAMP()-INTERVAL 1 HOUR GROUP BY l.project_id,p.title ORDER BY total DESC LIMIT 6')->fetchAll();
$pageTitle='Engagement';$active='engagement';require __DIR__.'/_header.php';
?>
<div class="page-heading"><div><p class="eyebrow">COMMUNITY REACTIONS</p><h1>Likes & <span class="accent">ratings.</span></h1><p>Review project feedback and moderate suspected abuse.</p></div><a class="button button-small" href="<?= e(url('admin/settings.php#visibility')) ?>">Global visibility settings ↗</a></div>
<div class="dashboard-panels"><section class="panel"><h2>Rating distribution</h2><?php $max=max(1,...array_map(fn($x)=>(int)$x['total'],$dist));foreach ($dist as $r): ?><div class="bar-row"><div><span><?= (int)$r['stars'] ?> stars</span><strong><?= (int)$r['total'] ?></strong></div><div class="bar-track"><div class="bar-fill" style="width:<?= round((int)$r['total']/$max*100) ?>%"></div></div></div><?php endforeach; ?><?php if (!$dist): ?><p class="muted">No ratings recorded.</p><?php endif; ?></section>
<section class="panel"><h2>Recent activity (last hour)</h2><?php if (!$recentSpike): ?><p class="muted">No likes in the last hour.</p><?php endif; ?><?php foreach ($recentSpike as $r): ?><div class="rank-item"><strong><?= e($r['title']) ?></strong><em><?= (int)$r['total'] ?> likes</em></div><?php endforeach; ?><p class="hint">Unexpected spikes may indicate suspicious traffic. Rate limits and unique browser IDs reduce ordinary duplicates but cannot prevent all manipulation.</p></section></div>
<section class="panel"><div class="panel-head"><h2>Engagement by project</h2></div><div class="table-scroll"><table><thead><tr><th>Project</th><th>Likes</th><th>Average</th><th>Ratings</th><th>Views</th><th>Options</th></tr></thead><tbody><?php foreach ($projects as $p): ?><tr><td><strong><?= e($p['title']) ?></strong></td><td><?= (int)$p['likes_count'] ?></td><td>★ <?= number_format((float)$p['average_rating'],2) ?></td><td><?= (int)$p['ratings_count'] ?></td><td><?= (int)$p['views_count'] ?></td><td><a href="<?= e(url('admin/project-edit.php?id='.$p['id'])) ?>">Project controls ↗</a> · <a href="<?= e(url('admin/project-analytics.php?id='.$p['id'])) ?>">Insights ↗</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="dashboard-panels"><section class="panel"><h2>Latest star ratings</h2><div class="table-scroll"><table><thead><tr><th>Project</th><th>Stars</th><th>Time (UTC)</th><th></th></tr></thead><tbody><?php foreach ($votes as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= str_repeat('★',(int)$r['stars']) ?></td><td><?= e($r['updated_at']) ?></td><td><form method="post" data-confirm="Remove this rating as abusive or fraudulent?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button name="action" value="remove_rating" class="text-btn danger">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><h2>Latest hearts</h2><div class="table-scroll"><table><thead><tr><th>Project</th><th>Time (UTC)</th><th></th></tr></thead><tbody><?php foreach ($likes as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['created_at']) ?></td><td><form method="post" data-confirm="Remove this suspicious like?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button name="action" value="remove_like" class="text-btn danger">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
